   var world=new WorldProject{GeoReference=reference};for(var x=0;x<3;x++){var p=MapGenerator.Generate(new(){Kind="blank",Size=256});p.WorldX=100+x;p.WorldY=100;p.WorldSection=true;p.Version=6;world.Maps.Add(new(){Project=p});}WorldAssembler.Validate(world);
   var ring=new[]{(252,30),(264,30),(264,42),(252,42),(252,30)}.Select(p=>{var g=projection.Geographic(p.Item1,p.Item2);return new[]{g.Longitude,g.Latitude};}).ToArray();
