   var report=GeographicImporter.TransferCheck(json,world);Check(report.Passed&&report.ByKind["building"].PlacedWorld==1,"Whole-world transfer report rejected the aggregate source");Reject(()=>GeographicImporter.Import(json,world.Maps[0].Project,bounds));
