  yield return("incomplete OSM points and relation holes are omitted with warning",()=>{
   var source="""{"elements":[{"type":"way","id":1,"tags":{"highway":"path"},"geometry":[{"lon":30,"lat":50},{"lon":30.004,"lat":50.004}]},{"type":"way","id":2,"tags":{"building":"house"},"geometry":[{"lon":30.001,"lat":50.001},{},{"lon":30.002,"lat":50.002},{"lon":30.001,"lat":50.001}]},{"type":"relation","id":3,"tags":{"natural":"water"},"members":[{"type":"way","role":"outer","geometry":[{"lon":30,"lat":50},{"lon":30.004,"lat":50},{"lon":30.004,"lat":50.004},{"lon":30,"lat":50.004},{"lon":30,"lat":50}]},{"type":"way","role":"inner","geometry":[{"lon":30.001,"lat":50.001},{"lon":30.003,"lat":50.001}]}]}]}""";
   var result=GeographicImporter.Import(source,MapGenerator.Generate(new(){Kind="blank"}));Check(result.Project.Buildings.Count==0&&!result.Project.Terrain.Contains(Terrain.Water)&&result.Warnings.Any(w=>w.Contains("missing points")),"Incomplete geometry became usable contour");
