  yield return("tiled OSM retries deduplicates full way geometry and records cache date",()=>WithDirectory(root=>{
   var handler=new SequenceHandler([new(HttpStatusCode.GatewayTimeout),Response(Road(30,50,30.02,50.02)),Response(Road(30,50,30.02,50.02))]);using var client=new OsmClient(root,handler,TimeSpan.Zero,TimeSpan.FromSeconds(1));var reports=new List<OsmProgress>();var bounds=new GeoBounds{West=30,East=30.001,South=50,North=50.015};var result=client.FetchTiledDetailed(bounds,default,new TestProgress(reports.Add)).GetAwaiter().GetResult();using var json=JsonDocument.Parse(result.Data);Check(handler.Calls==3&&json.RootElement.GetProperty("elements").GetArrayLength()==1&&json.RootElement.GetProperty("elements")[0].GetProperty("geometry")[1].GetProperty("lat").GetDouble()==50.02,"Retry/dedup truncated full geometry");Check(result.DataTimestamp=="2026-10-13T00:00:00Z"&&reports.Any(p=>p.Warning is not null),"Source date/progress missing");var cached=client.FetchTiledDetailed(bounds,default).GetAwaiter().GetResult();Check(cached.FromCache&&cached.Requests==0&&handler.Calls==3&&cached.DataTimestamp==result.DataTimestamp,"Cache metadata missing");
  }));
  yield return("world OSM jobs return only complete sparse world and cancelled job keeps input",()=>WithDirectory(root=>{
   var assets=new GameAssetCatalog(root,Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"");using var client=new OsmClient(Path.Combine(root,"cache"),new SequenceHandler([Response(Road(30,50.006,30.01,50))]),TimeSpan.Zero);using var service=new OsmWorldImportService(client,assets,Path.Combine(root,"jobs"));var request=new OsmWorldImportRequest(new(){West=30,East=30.01,South=50,North=50.006},SectionSize:512,SourceMode:"overpass");var started=JsonSerializer.SerializeToElement(service.Start(request));var id=started.GetProperty("id").GetString()!;Wait(service,id);using var file=File.OpenRead(service.ResultFile(id));var world=JsonSerializer.Deserialize<WorldProject>(file,new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;Check(world.Maps.Count==4&&world.GeoReference?.MetresPerTile==1&&WorldAssembler.Validate(world).Width==1024,"World geometry frame/sections missing");
   var before=JsonSerializer.Serialize(world);using var pending=new OsmClient(Path.Combine(root,"pending"),new PendingHandler(),TimeSpan.Zero);using var cancelled=new OsmWorldImportService(pending,assets,Path.Combine(root,"cancelled"));var another=request with{ExistingWorld=world,PreserveEdits=true};var cancelId=JsonSerializer.SerializeToElement(cancelled.Start(another)).GetProperty("id").GetString()!;cancelled.Cancel(cancelId);Wait(cancelled,cancelId,"cancelled");Reject(()=>cancelled.ResultFile(cancelId));Check(JsonSerializer.Serialize(world)==before,"Cancellation changed original world");
